const s = (v) => (v === undefined || v === null) ? null : String(v).trim();
const j = $json;
const kind = s(j.ask_kind) || "question";
if (kind !== "question" && kind !== "signoff") throw new Error("ask_fr: unknown ask_kind: " + kind);
const question = s(j.question);
if (!question) throw new Error("ask_fr: question is empty");
const hours = Number(j.expires_in_hours);
return [{ json: {
  card_id: s(j.card_id), board_id: s(j.board_id), project_id: s(j.project_id),
  list: s(j.list), card_type: s(j.card_type), slot: s(j.slot) || "",
  ask_kind: kind, question: question, draft: s(j.draft) || "",
  field: s(j.field) || "", artifact_ref: s(j.artifact_ref) || "",
  expires_in_hours: (Number.isFinite(hours) && hours > 0) ? hours : 24
} }];

const asked = $("Ask object").first().json;
const raised = $("Raise ask").first().json;
const raw = $input.first().json;
const d = (raw && raw.data && typeof raw.data === "object") ? raw.data : raw;
const decisions = Array.isArray(d.decisions) ? d.decisions : [];
const last = decisions.length ? decisions[decisions.length - 1] : null;
const approvalId = d.id || (raised && raised.data && raised.data.id) || null;
const decision = (last && last.decision) ? last.decision : (d.status || null);
const text = (last && last.comment !== undefined && last.comment !== null) ? String(last.comment) : "";
// fr keeps one open gate per card: a deduplicated raise returned an OLDER approval, and the Wait resumed when THAT one was decided.
// Same question -> its answer is ours. A different question -> its answer is not ours: raise this question again, once.
const md = (raised && raised.data && raised.data.metadata) || {};
const theirs = String(md.question || (Array.isArray(md.open_questions) ? md.open_questions[0] : "") || (raised && raised.data && raised.data.description) || "").trim();
const foreign = !!(raised && raised.deduplicated === true) && theirs !== asked.question;
return [{ json: {
  approval_id: approvalId,
  decision: foreign ? "deduplicated" : decision,
  answer: foreign ? "" : text,
  has_answer: foreign ? false : text.trim() !== "",
  answered_by_kind: (!foreign && last && last.decided_by_kind) ? last.decided_by_kind : null,
  field: asked.field, draft: asked.draft, question: asked.question,
  ask_kind: asked.ask_kind, card_id: asked.card_id,
  ask_again: foreign && $runIndex === 0
} }];

const flow = $('Ask object').first().json;
const p = $input.first().json;
const ids = (p.planka_list_ids !== undefined && p.planka_list_ids !== null) ? p.planka_list_ids : {};
const key = String(flow.list || 'DOING').toUpperCase();
const pick = (k) => (ids[k] !== undefined && ids[k] !== null) ? String(ids[k]) : null;
return [{ json: Object.assign({}, flow, {
  project_id: (p.project_id !== undefined && p.project_id !== null) ? p.project_id : flow.project_id,
  list_id: pick(key) || pick('DOING'),
  doing_list_id: pick('DOING'),
  blocked_list_id: pick('BLOCKED')
}) }];
